-- FaGe (Fachfrau/Fachmann Gesundheit EFZ): Bildungsplan-Fragenkatalog (16 × 30 Fragen).
-- Idempotent, additiv und ohne Datenverlust:
--   * course_key-CHECK-Constraints werden auf
--     abu/automechaniker/fage/schreiner/strassenbau erweitert.
--   * Module werden nach (course_key, title) gesucht oder angelegt.
--   * Lektionen werden nach (module_id, title) gesucht oder angelegt;
--     position/pass_score werden gesetzt.
--   * Fragen werden positionsbasiert UPSERTet: vorhandene (lesson_id,
--     position) werden aktualisiert (question.id bleibt erhalten, FKs zu
--     question_xp_awards / battle_answers bleiben intakt). Fehlende
--     Positionen werden eingefügt. Positionen > 30 werden entfernt.
--   * Profile, lesson_progress, lesson_attempts werden nicht angetastet.

begin;

-- ============================================================
-- 1) course_key-CHECK-Constraints erweitern
-- ============================================================
do $$
begin
  if exists (select 1 from pg_constraint where conname = 'profiles_active_course_key_ck') then
    alter table public.profiles drop constraint profiles_active_course_key_ck;
  end if;
  alter table public.profiles
    add constraint profiles_active_course_key_ck check (active_course_key in ('abu', 'automechaniker', 'fage', 'schreiner', 'strassenbau'));
end$$;

do $$
begin
  if exists (select 1 from pg_constraint where conname = 'modules_course_key_ck') then
    alter table public.modules drop constraint modules_course_key_ck;
  end if;
  alter table public.modules
    add constraint modules_course_key_ck check (course_key in ('abu', 'automechaniker', 'fage', 'schreiner', 'strassenbau'));
end$$;

do $$
begin
  if to_regclass('public.battle_matches') is not null then
    if exists (select 1 from pg_constraint where conname = 'battle_matches_course_key_ck') then
      alter table public.battle_matches drop constraint battle_matches_course_key_ck;
    end if;
    alter table public.battle_matches
      add constraint battle_matches_course_key_ck check (course_key in ('abu', 'automechaniker', 'fage', 'schreiner', 'strassenbau'));
  end if;
end$$;

-- ============================================================
-- 2) FAGE: 1 Modul, 16 Lektionen je 30 Fragen
-- ============================================================
do $$
declare
  v_module_id uuid;
  v_lesson_id uuid;
begin
  select id into v_module_id from public.modules where course_key = 'fage' and title = 'Fachfrau/Fachmann Gesundheit EFZ – Bildungsplan' limit 1;
  if v_module_id is null then
    insert into public.modules (title, description, course_key, position)
    values ('Fachfrau/Fachmann Gesundheit EFZ – Bildungsplan', 'Bildungsplan Fachfrau/Fachmann Gesundheit EFZ (OdASanté/SBFI). 16 Lektionen entlang der Handlungskompetenzbereiche HKB A–H mit Fokus auf Berufsidentität, Pflege und Betreuung, Alltagsgestaltung, Medizinaltechnik, Krise/Notfall, Hygiene/Sicherheit, Logistik und Administration.', 'fage', 100)
    returning id into v_module_id;
  else
    update public.modules set description = 'Bildungsplan Fachfrau/Fachmann Gesundheit EFZ (OdASanté/SBFI). 16 Lektionen entlang der Handlungskompetenzbereiche HKB A–H mit Fokus auf Berufsidentität, Pflege und Betreuung, Alltagsgestaltung, Medizinaltechnik, Krise/Notfall, Hygiene/Sicherheit, Logistik und Administration.', position = 100 where id = v_module_id;
  end if;

  -- Lektion L01: L01 – Berufsidentität, Teamarbeit und Qualität
  select id into v_lesson_id from public.lessons where module_id = v_module_id and title = 'L01 – Berufsidentität, Teamarbeit und Qualität' limit 1;
  if v_lesson_id is null then
    insert into public.lessons (module_id, title, position, pass_score)
    values (v_module_id, 'L01 – Berufsidentität, Teamarbeit und Qualität', 10, 70)
    returning id into v_lesson_id;
  else
    update public.lessons set position = 10, pass_score = 70 where id = v_lesson_id;
  end if;
  update public.questions set prompt = 'Welche Aussage beschreibt das Thema Rolle als Berufsperson im Beruf Fachfrau/Fachmann Gesundheit EFZ am besten?', option_a = 'im eigenen Kompetenzbereich verantwortungsvoll und teamorientiert handeln', option_b = 'ärztliche Entscheidungen allein treffen im konkreten Auftrag', option_c = 'Aufgaben ohne Rückmeldung liegen lassen im laufenden Tagesgeschäft', option_d = 'Standards nach persönlicher Vorliebe ersetzen im Werkstattumfeld', correct_option = 'A', explanation = 'FaGe handeln professionell innerhalb ihres Kompetenzbereichs und in Zusammenarbeit mit dem Team.' where lesson_id = v_lesson_id and position = 1;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Welche Aussage beschreibt das Thema Rolle als Berufsperson im Beruf Fachfrau/Fachmann Gesundheit EFZ am besten?', 'im eigenen Kompetenzbereich verantwortungsvoll und teamorientiert handeln', 'ärztliche Entscheidungen allein treffen im konkreten Auftrag', 'Aufgaben ohne Rückmeldung liegen lassen im laufenden Tagesgeschäft', 'Standards nach persönlicher Vorliebe ersetzen im Werkstattumfeld', 'A', 'FaGe handeln professionell innerhalb ihres Kompetenzbereichs und in Zusammenarbeit mit dem Team.', 1); end if;
  update public.questions set prompt = 'Worauf muss man beim Thema Rolle als Berufsperson in der Praxis besonders achten?', option_a = 'ärztliche Entscheidungen allein treffen im üblichen Berufsalltag', option_b = 'im eigenen Kompetenzbereich verantwortungsvoll und teamorientiert handeln', option_c = 'Aufgaben ohne Rückmeldung liegen lassen nach gängiger Praxis', option_d = 'Standards nach persönlicher Vorliebe ersetzen unter typischen Arbeitsbedingungen', correct_option = 'B', explanation = 'FaGe handeln professionell innerhalb ihres Kompetenzbereichs und in Zusammenarbeit mit dem Team.' where lesson_id = v_lesson_id and position = 2;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Worauf muss man beim Thema Rolle als Berufsperson in der Praxis besonders achten?', 'ärztliche Entscheidungen allein treffen im üblichen Berufsalltag', 'im eigenen Kompetenzbereich verantwortungsvoll und teamorientiert handeln', 'Aufgaben ohne Rückmeldung liegen lassen nach gängiger Praxis', 'Standards nach persönlicher Vorliebe ersetzen unter typischen Arbeitsbedingungen', 'B', 'FaGe handeln professionell innerhalb ihres Kompetenzbereichs und in Zusammenarbeit mit dem Team.', 2); end if;
  update public.questions set prompt = 'Welche Aussage zum Thema Rolle als Berufsperson ist fachlich korrekt?', option_a = 'ärztliche Entscheidungen allein treffen im Werkstattumfeld', option_b = 'Aufgaben ohne Rückmeldung liegen lassen im Produktionsalltag', option_c = 'im eigenen Kompetenzbereich verantwortungsvoll und teamorientiert handeln', option_d = 'Standards nach persönlicher Vorliebe ersetzen bei sachgemässem Ablauf', correct_option = 'C', explanation = 'FaGe handeln professionell innerhalb ihres Kompetenzbereichs und in Zusammenarbeit mit dem Team.' where lesson_id = v_lesson_id and position = 3;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Welche Aussage zum Thema Rolle als Berufsperson ist fachlich korrekt?', 'ärztliche Entscheidungen allein treffen im Werkstattumfeld', 'Aufgaben ohne Rückmeldung liegen lassen im Produktionsalltag', 'im eigenen Kompetenzbereich verantwortungsvoll und teamorientiert handeln', 'Standards nach persönlicher Vorliebe ersetzen bei sachgemässem Ablauf', 'C', 'FaGe handeln professionell innerhalb ihres Kompetenzbereichs und in Zusammenarbeit mit dem Team.', 3); end if;
